mapper.select:
/* User.getCountOfFindUserList */
select count(*) as tot_cnt
from tb_user a

mapper.insert:
/* User.insertUser */
insert into tb_user
(
	/* user_no generate */
	user_id
	, user_name
	, password
	, birth_dt
	, join_dt
	, user_tel
	, emergency_tel
	, depart
	, `position`
	, user_auth
	, user_email
	, post_code
	, addr_basic
	, addr_detail
	, addr_extra
	, use_yn
	, file_path
	, reg_dt
	, reg_no
	, mod_dt
	, mod_no
)
values
(
	#{userId}
	, #{userName}
	, #{password}
	, #{birthDt}
	, #{joinDt}
	, #{userTel}
	, #{emergencyTel}
	, #{depart}
	, #{position}
	, #{userAuth}
	, #{userEmail}
	, #{postCode}
	, #{addrBasic}
	, #{addrDetail}
	, #{addrExtra}
	, 'Y'
	, #{filePath}
	, now()
	, #{regUserNo}
	, now()
	, #{regUserNo}
)

mapper.update:
/* User.updateUser */
update tb_user
set
	user_name		= #{userName}
	, birth_dt		= #{birthDt}
	, join_dt		= #{joinDt}
	, user_tel		= #{userTel}
	, emergency_tel	= #{emergencyTel}
	, depart		= #{depart}
	, `position`	= #{position}
	, user_auth		= #{userAuth}
	, user_email	= #{userEmail}
	, post_code		= #{postCode}
	, addr_basic	= #{addrBasic}
	, addr_detail	= #{addrDetail}
	, addr_extra	= #{addrExtra}
	, use_yn		= ifnull(#{useYn}, 'N')

	, file_path		= #{filePath}

	, mod_dt		= now()
	, mod_no		= #{regUserNo}
where user_no = #{userNo}

/* User.updateAnnual */ update tb_annual a set
tot_annual_day = (select case when timestampdiff(month, #{joinDt}, date_format(now(), '%Y%m%d')) < 12 then timestampdiff(month, #{joinDt}, date_format(now(), '%Y%m%d')) else 15 + ((timestampdiff(year, #{joinDt}, date_format(now(), '%Y%m%d')) - 1) div 2) end ) ,
used_annual_day = (select ifnull(sum(b.occur_day), 0) from tb_annual_used b where b.occur_dt like concat(date_format(now(), '%Y'), '%') and b.annual_type = 'use' ) , add_annual_day = (select ifnull( sum(b.occur_day), 0) from tb_annual_used b where b.occur_dt like concat(date_format(now(), '%Y'), '%') and b.annual_type = 'add') where `year` = date_format(now(), '%Y') and user_no = #{userNo}

mapper.select:
/* User.findUserId */
select count(*) as cnt
from tb_user
where user_id = #{userId}

mapper.insert:
/* User.insertAnnualInfo */
insert into tb_annual_used
(
	/* annual_no generate */
	user_no
	, occur_dt
	, annual_type
	, reason
	, occur_day
	, reg_dt
	, reg_no
	, mod_dt
	, mod_no
)
values
(
	#{userNo}
	, #{occurDt}
	, #{annualType}
	, #{reason}
	, #{occurDay}
	, now()
	, #{regUserNo}
	, now()
	, #{regUserNo}
)

mapper.update:
/* User.updateAnnualInfo */
update tb_annual_used
set
	occur_dt = #{occurDt}
	, annual_type = #{annualType}
	, reason = #{reason}
	, occur_day = #{occurDay}
where annual_no = #{annualNo}
and user_no = #{userNo}

mapper.delete:
/* User.deleteAnnualInfo */
delete from tb_annual_used
where annual_no = #{annualNo}
